(() => {
  'use strict';
  const E=window.BeadEngine, $=id=>document.getElementById(id);
  const icons={download:'M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 16v4h16v-4',book:'M12 5v15M12 5C8 2 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Z',folder:'M3 7V5h7l2 2h9v13H3V7Z',shield:'m12 3 8 3v6c0 4-5 8-8 9-3-1-8-5-8-9V6l8-3Zm-4 9 3 3 5-6',chevron:'m6 9 6 6 6-6',rotate:'M20 9a8 8 0 1 0 0 7M20 3v6h-6',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',fit:'M8 4H4v4m12-4h4v4M4 16v4h4m12-4v4h-4M9 9h6v6H9Z',check:'m5 12 4 4L19 6',arrow:'M4 12h15m-5-5 5 5-5 5',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',cursor:'m5 3 14 9-7 1-3 7-4-17Z',pencil:'m15 4 5 5M4 20l1-6L16 3l5 5-11 11-6 1Z',undo:'M9 5 4 10l5 5M4 10h11a5 5 0 0 1 0 10',refresh:'M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5',save:'M5 3h13l3 3v15H3V3h2Zm2 0v7h10V3M7 21v-7h10v7',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',close:'m6 6 12 12M6 18 18 6',image:'M3 3h18v18H3V3Zm0 14 5-6 4 4 3-4 6 7M15 7h.01',file:'M13 3H5v18h14V9l-6-6Zm0 0v6h6M8 14h8m-8 3h8',grid:'M3 3h18v18H3V3Zm6 0v18m6-18v18M3 9h18M3 15h18',printer:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 13h12v8H6v-8Z'};
  function icon(name) { return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.grid}"></path></svg>`; }
  function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
  fillIcons();
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=n=>new Intl.NumberFormat('en-US').format(n);
  const state={settings:{stitch:'peyote',width:40,rows:56,beadLength:1.3,beadDiameter:2,maxColors:6,fit:'contain',scale:90,contrast:0,background:'#cbd7bd',rotation:0,simplify:false},source:null,sourceData:'',sourceName:'Woodland fox',geometry:null,palette:[],colors:[],guide:[],view:'beads',zoom:100,tool:'inspect',activeColor:0,step:0,highlight:false,edits:false,undo:[],selectedId:null,version:1};
  const stitchNames={peyote:'Even-count peyote',raw:'Four-bead right-angle weave',square:'Square stitch'};
  const colorNames=[['#f8f3e6','Ivory'],['#ffffff','White'],['#e0d9c8','Oat'],['#aeae9e','Stone'],['#191f24','Ink'],['#4b3732','Cocoa'],['#9a5c35','Rust'],['#cf773e','Clay'],['#efad50','Marigold'],['#ffdd84','Butter'],['#b44f3e','Terracotta'],['#bc3653','Rose'],['#e49eae','Blush'],['#774b86','Plum'],['#a0a1ca','Lavender'],['#344e78','Indigo'],['#729eaf','Sky'],['#468986','Teal'],['#344a34','Forest'],['#819879','Sage'],['#b0bd8b','Meadow'],['#cbd7bd','Pale sage']].map(([h,n])=>({lab:E.lab(E.rgb(h)),name:n}));
  function colorName(h){return colorNames[E.nearest(E.lab(E.rgb(h)),colorNames.map(c=>c.lab))].name;}
  const fg=h=>E.lab(E.rgb(h))[0]>.66?'#34402c':'#ffffff';
  let toastTimer, generateTimer, loadToken=0, painting=false, paintChanged=false, longAction=false;
  function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4300);}
  function modal(title,body,eyebrow='BEADFORM STUDIO'){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalEyebrow').textContent=eyebrow;fillIcons($('modal'));if(!$('modal').open)$('modal').showModal();}
  $('closeModal').onclick=()=>$('modal').close();
  $('modal').addEventListener('close',()=>syncInputs());
  $('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
  function confirmReset(action){if(!state.edits){action();return;}modal('Start fresh from your image?',`<p class="modal-copy">Changing the image or pattern settings regenerates all bead colors. Your manual color and bead edits will be replaced. Save an editable project first if you want to keep them.</p><div class="confirm-actions"><button class="button secondary" id="cancelReset">Keep edits</button><button class="button primary" id="acceptReset">Regenerate</button></div>`);$('cancelReset').onclick=()=>{$('modal').close();syncInputs();};$('acceptReset').onclick=()=>{$('modal').close();state.edits=false;action();};}
  function sampleSVG(kind){
    const start='<svg xmlns="http://www.w3.org/2000/svg" width="500" height="500" viewBox="0 0 500 500">';
    if(kind==='fox')return start+'<path fill="#c66d38" d="M116 290 81 80 206 144h89L419 80l-36 210-133 143Z"/><path fill="#6b4030" d="m109 111 26 130 56-79Zm282 0-27 130-56-79Z"/><path fill="#e4a15b" d="m159 178 53-32h76l53 32-55 162-36 47-36-47Z"/><path fill="#faf3df" d="m94 260 93-22 63 149 63-149 93 22-61 93-95 80-95-80Z"/><path fill="#282d27" d="m158 231 43 10-9 26-34-5Zm184 0-43 10 9 26 34-5ZM226 357h48l-24 29Z"/><path fill="#c66d38" d="m110 289-42-20 45 66 62 23Zm280 0 42-20-45 66-62 23Z"/></svg>';
    if(kind==='butterfly')return start+'<path fill="#526c50" d="M240 233C209 123 100 41 54 94 14 145 65 249 199 270 87 266 75 351 124 402 175 455 225 358 247 293ZM260 233C291 123 400 41 446 94c40 51-11 155-145 176 112-4 124 81 75 132-51 53-101-44-123-109Z"/><path fill="#cba568" d="M219 238C177 141 99 93 90 128c-9 35 48 95 129 110ZM281 238c42-97 120-145 129-110 9 35-48 95-129 110ZM217 302c-55-7-91 37-72 60s54-17 72-60ZM283 302c55-7 91 37 72 60s-54-17-72-60Z"/><path stroke="#2d3d30" stroke-width="12" stroke-linecap="round" fill="none" d="m243 208-30-50m44 50 30-50"/><path fill="#2d3d30" d="M238 213q12-22 24 0l6 82-18 76-18-76Z"/></svg>';
    return start+'<path fill="#af4d46" d="M250 421 78 255C-17 154 125 32 216 128l34 35 34-35c91-96 233 26 138 127Z"/><path fill="#dc8c79" d="M101 196c-25-58 36-103 83-51l-21 27c-23-25-46-12-37 15Z"/></svg>';
  }
  const sampleData={};
  function loadImage(url){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('This image could not be decoded. Try a PNG, JPG, or WebP image.'));img.src=url;});}
  function normaliseImage(img,maxSide=1600){const cv=document.createElement('canvas'),scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight));cv.width=Math.max(1,Math.round(img.naturalWidth*scale));cv.height=Math.max(1,Math.round(img.naturalHeight*scale));cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);return cv.toDataURL('image/png');}
  async function chooseSample(kind,initial=false){const token=++loadToken;try{const url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(sampleSVG(kind));const img=await loadImage(url);const data=normaliseImage(img);const safeImage=await loadImage(data);if(token!==loadToken)return;sampleData[kind]=data;state.source=safeImage;state.sourceData=data;state.sourceName={fox:'Woodland fox',butterfly:'Meadow butterfly',heart:'A little love'}[kind];$('projectTitle').value=state.sourceName;state.settings.rotation=0;state.settings.scale=90;state.settings.contrast=0;state.settings.background='#cbd7bd';document.querySelectorAll('.sample').forEach(e=>e.classList.toggle('active',e.dataset.sample===kind));syncInputs();generate(true);if(!initial)toast('A new little inspiration, ready to stitch.');}catch(e){toast(e.message);}}
  function initSamples(){for(const [kind,label] of [['butterfly','Butterfly']]){$('samples').insertAdjacentHTML('beforeend',`<button class="sample ${kind==='fox'?'active':''}" data-sample="${kind}" title="Try ${label.toLowerCase()} motif" aria-label="Try ${label.toLowerCase()} motif"><img alt="" src="${esc('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(sampleSVG(kind)))}"><span>${label}</span></button>`);}document.querySelectorAll('.sample').forEach(b=>b.onclick=()=>confirmReset(()=>chooseSample(b.dataset.sample)));}
  async function upload(file){if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)){toast('Please choose a PNG, JPG, or WebP image.');return;}if(file.size>20*1024*1024){toast('Please choose an image smaller than 20 MB.');return;}const token=++loadToken, url=URL.createObjectURL(file);try{const img=await loadImage(url);if(img.naturalWidth*img.naturalHeight>60000000)throw Error('This image is very large. Resize it below 60 megapixels and try again.');const data=normaliseImage(img),safe=await loadImage(data);if(token!==loadToken)return;confirmReset(()=>{state.source=safe;state.sourceData=data;state.userUploaded=true;state.sourceName=file.name.slice(0,100);$('projectTitle').value=file.name.replace(/\.[^.]+$/,'').slice(0,70)||'My pattern';state.settings.rotation=0;document.querySelectorAll('.sample').forEach(e=>e.classList.remove('active'));syncInputs();generate(true);toast('Image ready. Adjust the stitch, size, and colors to bring it into focus.');});}catch(e){toast(e.message);}finally{URL.revokeObjectURL(url);$('fileInput').value='';}}
  function syncInputs(){const s=state.settings;for(const id of ['width','rows','beadLength','beadDiameter','maxColors','fit','scale','contrast','background'])$(id).value=s[id];$('simplify').checked=s.simplify;$('maxColorsValue').value=s.maxColors;$('scaleValue').value=s.scale+'%';$('contrastValue').value=s.contrast;document.querySelectorAll('[data-stitch]').forEach(e=>{const on=e.dataset.stitch===s.stitch;e.classList.toggle('active',on);e.setAttribute('aria-pressed',on);});$('widthLabel').textContent=s.stitch==='peyote'?'Starter beads':s.stitch==='raw'?'Units across':'Beads across';$('rowsLabel').textContent=s.stitch==='raw'?'Unit rows':'Stitch rows';$('width').min=s.stitch==='raw'?2:s.stitch==='peyote'?12:6;$('width').max=s.stitch==='raw'?30:80;$('width').step=s.stitch==='peyote'?2:1;$('rows').min=s.stitch==='raw'?2:6;$('rows').max=s.stitch==='raw'?40:120;$('sizeHint').textContent=s.stitch==='peyote'?`${s.width/2} beads per stitch row. The foundation makes rows 1 + 2.`:s.stitch==='raw'?'Each complete unit has four beads. Neighbors share one bead per side.':'Each bead aligns with the bead in the row below.';}
  function sourceCanvas(g){const s=state.settings,max=1400,cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(max*g.W/Math.max(g.W,g.H)));cv.height=Math.max(1,Math.round(max*g.H/Math.max(g.W,g.H)));const ctx=cv.getContext('2d',{willReadFrequently:true});ctx.fillStyle=s.background;ctx.fillRect(0,0,cv.width,cv.height);const angle=s.rotation*Math.PI/180,swap=s.rotation%180!==0,iw=swap?state.source.naturalHeight:state.source.naturalWidth,ih=swap?state.source.naturalWidth:state.source.naturalHeight;const fit=s.fit==='cover'?Math.max(cv.width/iw,cv.height/ih):Math.min(cv.width/iw,cv.height/ih);ctx.save();ctx.translate(cv.width/2,cv.height/2);ctx.rotate(angle);ctx.scale(fit*s.scale/100,fit*s.scale/100);ctx.drawImage(state.source,-state.source.naturalWidth/2,-state.source.naturalHeight/2);ctx.restore();return cv;}
  function sampleBeads(g,cv){const ctx=cv.getContext('2d',{willReadFrequently:true}),pixels=ctx.getImageData(0,0,cv.width,cv.height).data,sx=cv.width/g.W,sy=cv.height/g.H;return g.nodes.map(n=>{const acc=[0,0,0];for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++){const x=E.clamp(Math.round((n.x+a*n.w*.23)*sx),0,cv.width-1),y=E.clamp(Math.round((g.H-n.y+b*n.h*.23)*sy),0,cv.height-1),idx=(y*cv.width+x)*4;for(let j=0;j<3;j++)acc[j]+=pixels[idx+j];}return acc.map(v=>E.clamp((v/9-128)*(1+state.settings.contrast/100)+128,0,255));});}
  function generate(resetStep=false){if(!state.source)return;clearTimeout(generateTimer);try{const g=E.geometry(state.settings),cv=sourceCanvas(g),samples=sampleBeads(g,cv),q=E.quantize(samples,state.settings.maxColors);state.geometry=g;state.palette=q.palette;state.colors=state.settings.simplify?E.simplify(g,q.colors,q.palette):q.colors;state.guide=E.steps(g);state.edits=false;state.undo=[];state.selectedId=null;state.activeColor=Math.min(state.activeColor,state.palette.length-1);state.step=resetStep?0:Math.min(state.step,state.guide.length-1);state.sourcePreview=cv.toDataURL('image/png');$('sourceThumb').src=state.sourceData;$('sourceName').textContent=state.sourceName;renderAll();window.Beadform3D?.receiveFlatSource();}catch(e){toast(e.message);}}
  function settingsChange(id,value){clearTimeout(generateTimer);confirmReset(()=>{state.settings[id]=value;syncInputs();generate();});}
  function scheduleSetting(id,value){clearTimeout(generateTimer);generateTimer=setTimeout(()=>settingsChange(id,value),200);}
  function snapshot(){state.undo.push({colors:state.colors.slice(),palette:state.palette.slice(),edits:state.edits});if(state.undo.length>30)state.undo.shift();$('undoBtn').disabled=false;}
  function setTool(tool){state.tool=tool;for(const t of ['inspect','paint']){$(t+'Tool').classList.toggle('active',t===tool);$(t+'Tool').setAttribute('aria-pressed',t===tool);}$('patternStage').classList.toggle('paint',tool==='paint');if(tool==='paint'&&state.view==='source'){state.view='beads';renderChart();}if(tool==='paint')$('selectionInfo').textContent=`Painting ${E.code(state.activeColor)} · ${colorName(state.palette[state.activeColor])}. Click or drag over beads.`;}
  const indexCache=new WeakMap();
  function currentIndex(){const g=state.geometry;if(!indexCache.has(g))indexCache.set(g,new Map(g.nodes.map((n,i)=>[n.id,i])));return indexCache.get(g);}
  function counts(){const out=state.palette.map(()=>0);for(const c of state.colors)out[c]++;return out;}
  function renderPalette(){const cc=counts();$('paletteList').innerHTML=state.palette.map((h,i)=>`<div class="palette-row ${i===state.activeColor?'selected':''}"><label class="palette-swatch" title="Change color ${E.code(i)} for all matching beads"><input aria-label="Recolor all ${E.code(i)} beads" type="color" value="${h}" data-color="${i}"></label><button class="palette-pick" data-pick="${i}" aria-pressed="${i===state.activeColor}" aria-label="Paint with ${E.code(i)}, ${colorName(h)}"><span class="color-code">${E.code(i)}</span><span><span class="color-name">${colorName(h)}</span><span class="color-hex">${h}</span></span><span class="color-count">${num(cc[i])}</span></button></div>`).join('');$('paletteList').querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{state.activeColor=+b.dataset.pick;setTool('paint');renderPalette();});$('paletteList').querySelectorAll('[data-color]').forEach(input=>input.onchange=()=>{snapshot();state.palette[+input.dataset.color]=input.value;state.edits=true;renderAll();toast('Palette color updated throughout your pattern.');});}
  function renderStats(){const g=state.geometry,cc=counts(),valid=E.validate(g,state.colors,state.palette);state.validation=valid;$('totalBeads').textContent=num(g.nodes.length);$('paletteCount').innerHTML=`${cc.filter(c=>c>0).length} <span>colors</span>`;$('sizeEstimate').innerHTML=`${(g.W/10).toFixed(1)} × ${(g.H/10).toFixed(1)} <span>cm</span>`;$('structureStatus').innerHTML=valid.valid?icon('check')+'Connected':'Check pattern';$('structureStatus').classList.toggle('error-text',!valid.valid);$('validationSummary').textContent=!valid.valid?valid.errors.join(' '):g.stitch==='peyote'?'Even starter count, complete rows, and one connected panel.':g.stitch==='raw'?'Complete four-bead units. Shared beads are connected and counted once.':'Complete, aligned rows and one connected panel.';const a=E.accents(g,state.colors);$('qualityNote').textContent=a?`${num(a)} one-bead accent${a===1?'':'s'}. Inspect tiny details: eyes may be intentional; stray speckles may need paint.`:'No isolated single-bead colors detected.';$('undoBtn').disabled=!state.undo.length;}
  function chartSVG({symbols=state.view==='symbols',highlight=state.highlight,selected=true,exporting=false,tile=null}={}){
    const g=state.geometry,s=state.settings,margin=Math.max(g.L,g.D)*2.5,fs=Math.min(g.L,g.D)*.58,idx=currentIndex(),step=state.guide[state.step],hi=new Set(highlight?(step.kind==='unit'?step.cell.ids:step.ids):[]),pad=margin;
    const vb=tile?`${tile.x} ${tile.y} ${tile.w} ${tile.h}`:`${-pad} ${-pad} ${g.W+pad*2} ${g.H+pad*2}`;
    let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb}" role="img" aria-label="${esc(stitchNames[g.stitch])} chart for ${esc($('projectTitle').value)}, ${g.nodes.length} beads, rows read from bottom to top"><title>${esc($('projectTitle').value)} — ${esc(stitchNames[g.stitch])}</title><desc>Colors are identified by letters. Rows increase upward. Use the construction guide for pickup order.</desc>`;
    if(exporting)svg+=`<rect x="${-pad}" y="${-pad}" width="${g.W+pad*2}" height="${g.H+pad*2}" fill="#ffffff"/>`;
    if(!symbols)svg+='<defs><linearGradient id="beadShine" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".28"/><stop offset=".3" stop-color="#fff" stop-opacity=".05"/><stop offset=".78" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".07"/></linearGradient></defs>';
    if(g.stitch==='raw')for(const cell of g.cells){if(highlight&&step.cell&&cell.id!==step.cell.id)continue;const p=g.L+g.D;svg+=`<path d="M ${cell.x-p/2} ${g.H-cell.y} L ${cell.x} ${g.H-cell.y-p/2} L ${cell.x+p/2} ${g.H-cell.y} L ${cell.x} ${g.H-cell.y+p/2} Z" fill="none" stroke="#6e7d5933" stroke-width="${g.L*.045}"/>`;}
    const gap=symbols?.045:.08;
    for(const n of g.nodes){const color=state.colors[idx.get(n.id)],h=state.palette[color],w=n.w*(1-gap),ht=n.h*(1-gap),x=n.x-w/2,y=g.H-n.y-ht/2,rx=Math.min(w,ht)*(g.stitch==='raw'?.4:.2),opacity=hi.size&&!hi.has(n.id)?.18:1,select=selected&&state.selectedId===n.id;
      svg+=`<g data-bead="${n.id}"${select?' class="selected-bead"':''} opacity="${opacity}"><title>${n.id} · ${E.code(color)} ${h}</title><rect x="${x}" y="${y}" width="${w}" height="${ht}" rx="${rx}" fill="${h}" stroke="${select?'#cc7348':'#38483244'}" stroke-width="${Math.min(w,ht)*.04}"/>`;
      if(symbols)svg+=`<text x="${n.x}" y="${g.H-n.y}" dominant-baseline="central" text-anchor="middle" font-family="Arial,sans-serif" font-size="${Math.min(w,ht)*.68}" font-weight="500" fill="${fg(h)}" pointer-events="none">${E.code(color)}</text>`;
      else {svg+=`<rect x="${x}" y="${y}" width="${w}" height="${ht}" rx="${rx}" fill="url(#beadShine)" pointer-events="none"/>`;const horiz=n.orientation==='horizontal';svg+=`<path d="M ${n.x-(horiz?w*.22:0)} ${g.H-n.y-(horiz?0:ht*.22)} l ${horiz?w*.44:0} ${horiz?0:ht*.44}" stroke="${fg(h)}" stroke-opacity="${fg(h)==='#ffffff'?.12:.08}" stroke-width="${Math.min(w,ht)*.08}" stroke-linecap="round" pointer-events="none"/>`;}
      svg+='</g>';
    }
    const lab=(x,y,t,anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" dominant-baseline="central" fill="#83916f" font-size="${fs}" font-family="Arial,sans-serif">${t}</text>`;
    const every=g.R>80?10:g.R>36?5:2;
    for(let r=0;r<g.R;r++){if(r!==0&&r!==g.R-1&&(r+1)%every)continue;let y;if(g.stitch==='raw')y=(r+.5)*(g.L+g.D)+g.D/2;else y=(g.stitch==='peyote'?r/2+.5:r+.5)*g.D;svg+=lab(-pad*.43,g.H-y,r+1,'end');svg+=lab(g.W+pad*.43,g.H-y,r+1,'start');}
    const ce=g.C>40?10:5;for(let c=0;c<g.C;c++){if(c!==0&&c!==g.C-1&&(c+1)%ce)continue;const x=g.stitch==='raw'?(c+.5)*(g.L+g.D)+g.D/2:(c+.5)*g.L;svg+=lab(x,g.H+pad*.48,c+1);}
    if(g.stitch==='raw'&&highlight&&step.cell){const c=step.cell,p=g.L+g.D;svg+=`<text x="${c.x}" y="${g.H-c.y}" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="${Math.min(g.L,g.D)*.4}" fill="#3c5530">${c.r+1}.${c.c+1}</text>`;}
    return svg+'</svg>';
  }
  function renderChart(){if(!state.geometry)return;for(const v of ['beads','symbols','source']){$(v+'View').classList.toggle('active',state.view===v);$(v+'View').setAttribute('aria-pressed',state.view===v);}$('techniqueTag').textContent=stitchNames[state.settings.stitch].toUpperCase();$('patternStage').innerHTML=state.view==='source'?`<img src="${state.sourcePreview}" alt="Your image positioned within the panel">`:chartSVG();$('patternStage').style.width=state.zoom+'%';$('patternStage').style.height=state.zoom+'%';$('zoomValue').textContent=state.zoom+'%';$('boardNote').textContent=state.view==='source'?'Original image, fitted to the panel.':state.view==='symbols'?'Every letter matches your color key.':'A full panel. Every little bead belongs.';}
  function mini(c){const h=state.palette[c];return `<span class="mini-bead" style="background:${h};color:${fg(h)}">${E.code(c)}</span>`;}
  function runHTML(ids){return E.runs(ids,state.geometry,state.colors).map(r=>`<span class="color-run">${mini(r.color)}<span>${r.count}</span></span>`).join('');}
  function beadToken(id,kind){const i=currentIndex().get(id),c=state.colors[i];return `<span class="raw-token ${kind==='pass'?'pass':''}"><small>${kind||''}</small>${mini(c)} ${id}</span>`;}
  function rawHTML(step){return `<div class="raw-ops">${step.travel.length?`<div class="raw-line"><span class="raw-label">Move through</span>${step.travel.map(id=>beadToken(id,'pass')).join('<span>→</span>')}</div>`:''}<div class="raw-line"><span class="raw-label">Work the ring</span>${step.ops.map(op=>beadToken(op.id,op.kind)).join('<span>→</span>')}</div><div class="raw-line"><span class="raw-label">New beads</span>${step.ids.length} · Shared before this step: ${step.shared.length}</div></div>`;}
  function renderGuide(){const step=state.guide[state.step];if(!step)return;$('stepTitle').textContent=step.label;$('stepDirection').textContent=step.direction+' · work upward';$('stepCounter').textContent=`${state.step+1} / ${state.guide.length}`;$('stepNote').textContent=step.note;$('stepColors').innerHTML=step.kind==='unit'?rawHTML(step):runHTML(step.ids);$('prevStep').disabled=state.step===0;$('nextStep').disabled=state.step===state.guide.length-1;$('jumpStep').max=state.guide.length;$('jumpStep').value=state.step+1;$('highlight').checked=state.highlight;}
  function renderAll(){window.BeadJourney?.scheduleSave();renderChart();renderPalette();renderStats();renderGuide();}
  function goStep(n){window.BeadJourney?.scheduleSave();state.step=E.clamp(n,0,state.guide.length-1);renderGuide();if(state.highlight)renderChart();}
  function selectBead(id,applyPaint=false){const i=currentIndex().get(id);if(i===undefined)return;state.selectedId=id;const n=state.geometry.nodes[i];if(applyPaint&&state.colors[i]!==state.activeColor){if(!paintChanged)snapshot();state.colors[i]=state.activeColor;state.edits=true;paintChanged=true;renderChart();}else if(!applyPaint)renderChart();const c=state.colors[i];$('selectionInfo').innerHTML=`<b>${esc(id)}</b> · ${E.code(c)} ${esc(colorName(state.palette[c]))}<br>${state.geometry.stitch==='raw'?`${n.orientation} edge · labels count upward from the bottom`:`Row ${n.r+1}, position ${n.c+1} from the left`}${state.tool==='inspect'?'<br><button class="text-button" id="editSelectedBtn">Paint this bead</button>':''}`;if($('editSelectedBtn'))$('editSelectedBtn').onclick=()=>editBead(id);}
  function editBead(id){const i=currentIndex().get(id);modal('Give this bead a little color.',`<p class="modal-copy">${esc(id)} · choose a palette color.</p><div class="step-colors">${state.palette.map((h,c)=>`<button class="button secondary" data-assign="${c}">${mini(c)} ${E.code(c)} · ${colorName(h)}</button>`).join('')}</div>`);document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>{snapshot();state.colors[i]=+b.dataset.assign;state.edits=true;$('modal').close();renderAll();selectBead(id);});}
  function csv(){const g=state.geometry;return '\ufeffBead ID,Stitch,Row from bottom,Position from left,Orientation,Color symbol,Color hex\r\n'+g.nodes.map((n,i)=>[n.id,g.stitch,n.r+1,n.c+1,n.orientation,E.code(state.colors[i]),state.palette[state.colors[i]]].join(',')).join('\r\n');}
  function materialsCSV(){const cc=counts();return '\ufeffSymbol,Approximate color,Hex,Pattern beads,Prepare with 10% spare\r\n'+state.palette.map((h,i)=>[E.code(i),colorName(h),h,cc[i],Math.ceil(cc[i]*1.1)].join(',')).join('\r\n');}
  function textGuide(){const g=state.geometry,idx=currentIndex(),cc=counts(),s=state.settings;const lines=[`${$('projectTitle').value||'My pattern'} — BEADFORM`,`${stitchNames[g.stitch]} | flat panel | ${g.C} ${g.stitch==='raw'?'units across':g.stitch==='peyote'?'starter beads':'beads across'} × ${g.R} ${g.stitch==='raw'?'unit rows':'stitch rows'}`,`${g.nodes.length} physical beads | estimated ${(g.W/10).toFixed(1)} × ${(g.H/10).toFixed(1)} cm before finishing`,`Generic bead measurements: hole-axis length ${s.beadLength} mm; diameter ${s.beadDiameter} mm. Swatch to check size.`, '', 'COLOR KEY (screen colors, not manufacturer product codes)',...state.palette.map((h,i)=>`${E.code(i)}  ${h.toUpperCase()}  ${colorName(h)}: ${cc[i]} beads; prepare ${Math.ceil(cc[i]*1.1)} with 10% spare.`),'','READING THE CHART','Keep the chart fixed: columns run left to right and rows increase from bottom to top. Directions indicate the order of NEW beads, not the motion of your hands. Background cells are real beads.',''];
    if(g.stitch==='peyote')lines.push('The starter interleaves row 2 then row 1 at each column pair. String it in the listed order from left to right. After the starter, row 3 runs right to left. Each subsequent row alternates direction. P3-2 means row 3, second bead position in that stitch row from the left. Chart column numbers count starter positions.');
    if(g.stitch==='raw')lines.push('RAW edge IDs: H1-1 is the first horizontal bead along the bottom boundary. V1-1 is the first vertical bead on the left boundary. H rows number horizontal boundaries; V rows number bands of units. N/E/S/W in each unit mean north/east/south/west with the chart held upright. The same ID in adjacent units is ONE bead. Follow move-through beads first, then pick/pass operations. Pick means add; pass means go through an existing bead. Circling the ring reverses direction at neighboring units.');
    if(g.stitch==='square')lines.push('String row 1 left to right. Row 2 runs right to left, then alternate. For each new bead, loop through the bead directly below and back through the new bead; reinforce and turn at row ends. S3-2 means row 3, second bead from the left.');
    lines.push('','CONSTRUCTION');
    for(const step of state.guide){lines.push('',`${step.label} — ${step.direction}`);if(step.kind==='unit'){const c=step.cell;lines.push(`Map: N ${c.n}; E ${c.e}; S ${c.s}; W ${c.w}`);if(step.travel.length)lines.push('Move through: '+step.travel.map(id=>`${id} (${E.code(state.colors[idx.get(id)])})`).join(' → '));lines.push(step.ops.map(op=>`${op.kind.toUpperCase()} ${op.id} (${E.code(state.colors[idx.get(op.id)])})`).join(' → '));}else{lines.push(E.runs(step.ids,g,state.colors).map(r=>`${r.count}${E.code(r.color)}`).join(' · '));lines.push('Positions: '+step.ids.map(id=>`${id}=${E.code(state.colors[idx.get(id)])}`).join(', '));if(step.anchors)lines.push('Pass-through anchors after each new bead: '+step.anchors.join(', '));}lines.push(step.note);}
    lines.push('','FINISHING & SCOPE','Secure and weave in thread ends using your technique. Default supplies: size 11/0 round seed beads and 0.20–0.25 mm fishing line. Check the needle and repeated line passes fit the actual holes. Stop beads, thread, needles, clasps, borders, and other findings are not included in bead totals. This flat chart is a complete panel with no shaped edge increases/decreases. The separate 3D studio provides volume patterns. Structural checks verify the digital layout and bead inventory; a physical sample is still needed to check tension, scale, and likeness.','', 'TECHNIQUE REFERENCES','Peyote: https://www.firemountaingems.com/learn/categories/essential-resources/how-tos/H11S-video-tutorial-with-instructions.html','RAW: https://www.firemountaingems.com/learn/categories/essential-resources/how-tos/4B05-video-tutorial-with-instructions.html');return lines.join('\n');}
  function slug(){return ($('projectTitle').value||'beadform-pattern').normalize('NFKD').replace(/[^a-zA-Z0-9 _-]/g,'').trim().replace(/\s+/g,'-').slice(0,65)||'beadform-pattern';}
  function download(content,mime,suffix){const b=content instanceof Blob?content:new Blob([content],{type:mime}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=slug()+suffix;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Your download is ready.');}
  function saveProject(){if(!state.geometry)return;const data={finishedBuild:window.BeadJourney?.getBuild()||null,format:'beadform-project',version:1,dimension:'flat',title:$('projectTitle').value,sourceName:state.sourceName,sourceData:state.sourceData,settings:state.settings,palette:state.palette,colors:state.colors,step:state.step,manualEdits:state.edits};download(JSON.stringify(data), 'application/json','.beadform.json');}
  async function importProject(file){if(!file)return;try{if(file.size>24*1024*1024)throw Error('Choose a Beadform project under 24 MB.');const d=JSON.parse(await file.text());if(d.format!=='beadform-project'||d.version!==1||d.dimension!=='flat')throw Error('This is not a supported Beadform project.');const s=d.settings;if(!s||!['contain','cover'].includes(s.fit)||!/^#[0-9a-f]{6}$/i.test(s.background)||!Number.isInteger(s.maxColors)||s.maxColors<2||s.maxColors>12||![0,90,180,270].includes(s.rotation)||!Number.isFinite(s.scale)||s.scale<40||s.scale>160||!Number.isFinite(s.contrast)||s.contrast< -40||s.contrast>80||typeof s.simplify!=='boolean')throw Error('The project has invalid image settings.');if(s.stitch==='raw'&&(s.width>30||s.rows>40))throw Error('RAW projects support up to 30 units across and 40 unit rows.');const g=E.geometry(s);if(!Array.isArray(d.palette)||d.palette.length<1||d.palette.length>12||d.palette.some(h=>typeof h!=='string'||!/^#[0-9a-f]{6}$/i.test(h))||!Array.isArray(d.colors))throw Error('The project color key is invalid.');const valid=E.validate(g,d.colors,d.palette);if(!valid.valid)throw Error(valid.errors.join(' '));if(typeof d.sourceData!=='string'||!/^data:image\/png;base64,[a-zA-Z0-9+/=]+$/.test(d.sourceData))throw Error('The project must contain an embedded PNG source image.');const source=await loadImage(d.sourceData);if(source.naturalWidth>1600||source.naturalHeight>1600)throw Error('Project source images must be at most 1600 pixels on each side.');confirmReset(()=>{Object.assign(state,{settings:{stitch:s.stitch,width:s.width,rows:s.rows,beadLength:s.beadLength,beadDiameter:s.beadDiameter,maxColors:s.maxColors,fit:s.fit,scale:s.scale,contrast:s.contrast,background:s.background,rotation:s.rotation,simplify:s.simplify},geometry:g,palette:d.palette.slice(),colors:d.colors.slice(),guide:valid.guide,source,sourceData:d.sourceData,sourceName:typeof d.sourceName==='string'?d.sourceName.slice(0,100):'Saved image',step:Number.isInteger(d.step)?E.clamp(d.step,0,valid.guide.length-1):0,edits:!!d.manualEdits,undo:[],activeColor:0,selectedId:null});$('projectTitle').value=typeof d.title==='string'?d.title.slice(0,70):'My pattern';$('sourceThumb').src=state.sourceData;$('sourceName').textContent=state.sourceName;state.sourcePreview=sourceCanvas(g).toDataURL('image/png');syncInputs();renderAll();window.BeadJourney?.opened('flat',d);toast('Project opened, including your colors and stitch progress.');});}catch(e){toast(e instanceof SyntaxError?'This file is not valid project JSON.':e.message);}finally{$('projectInput').value='';}}
  function exportSVG(){const g=state.geometry,cc=counts(),pad=Math.max(g.L,g.D)*2.5,W=1100,plotH=Math.min(1800,Math.max(400,980*(g.H+pad*2)/(g.W+pad*2))),keyY=plotH+165,H=keyY+Math.ceil(state.palette.length/4)*53+100,title=($('projectTitle').value||'My pattern').slice(0,55),titleFont=Math.min(31,980/(Math.max(1,title.length)*.92));let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}"><rect width="${W}" height="${H}" fill="#fffef9"/><text x="55" y="54" font-family="Georgia,serif" font-size="${titleFont}" fill="#293d31">${esc(($('projectTitle').value||'My pattern').slice(0,55))}</text><text x="55" y="83" font-family="Arial,sans-serif" font-size="13" fill="#728067">${esc(stitchNames[g.stitch])} · ${g.nodes.length} beads · approx. ${(g.W/10).toFixed(1)} × ${(g.H/10).toFixed(1)} cm · BEADFORM</text><text x="55" y="108" font-family="Arial,sans-serif" font-size="12" fill="#849277">Rows increase upward. Follow the construction guide for pickup order. Background cells are beads.</text>`;svg+=chartSVG({symbols:true,highlight:false,selected:false,exporting:true}).replace('<svg ',`<svg x="55" y="132" width="990" height="${plotH}" `);svg+=`<text x="55" y="${keyY}" font-family="Arial" font-size="11" letter-spacing="2" fill="#6f7d63">COLOR KEY · SCREEN APPROXIMATIONS</text>`;state.palette.forEach((h,i)=>{const x=55+(i%4)*250,y=keyY+19+Math.floor(i/4)*53;svg+=`<rect x="${x}" y="${y}" width="30" height="30" rx="5" fill="${h}" stroke="#888" stroke-width=".5"/><text x="${x+15}" y="${y+20}" text-anchor="middle" font-family="Arial" font-size="15" fill="${fg(h)}">${E.code(i)}</text><text x="${x+41}" y="${y+12}" font-family="Arial" font-size="12" fill="#364a2c">${esc(colorName(h))} · ${cc[i]} beads</text><text x="${x+41}" y="${y+29}" font-family="Arial" font-size="10" fill="#849277">${h.toUpperCase()} · prepare ${Math.ceil(cc[i]*1.1)} with spare</text>`;});svg+=`<text x="55" y="${H-45}" font-family="Arial" font-size="11" fill="#849277">Bead dimensions: ${g.L} mm along the hole × ${g.D} mm diameter. Make a swatch to check final size.</text><text x="55" y="${H-24}" font-family="Arial" font-size="10" fill="#849277">Flat panel. Digital structure checked; physical fit, tension, and likeness require maker review. beadform.</text></svg>`;return {svg,W,H};}
  async function exportPNG(){if(longAction)return;longAction=true;try{const {svg,W,H}=exportSVG(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=await loadImage(url),cv=document.createElement('canvas'),scale=Math.min(2.5,4096/Math.max(W,H));cv.width=Math.round(W*scale);cv.height=Math.round(H*scale);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);const blob=await new Promise(resolve=>cv.toBlob(resolve,'image/png'));if(!blob)throw Error('The PNG could not be created. Try the SVG export.');download(blob,'image/png','-pattern.png');}finally{URL.revokeObjectURL(url);}}catch(e){toast(e.message);}finally{longAction=false;}}
  function printPattern(){const g=state.geometry,cc=counts(),idx=currentIndex();let out=`<section class="print-cover"><h1>${esc($('projectTitle').value||'My pattern')}</h1><p>${esc(stitchNames[g.stitch])} · ${num(g.nodes.length)} beads · estimated ${(g.W/10).toFixed(1)} × ${(g.H/10).toFixed(1)} cm</p><p>Overview. Detailed chart tiles, color key, and construction guide follow.</p><div class="print-chart">${chartSVG({symbols:true,highlight:false,selected:false,exporting:true})}</div></section>`;
    // Tiles use 4 mm per bead along the hole on A4, keeping every symbol readable.
    const targetScale=4/g.L,tw=180/targetScale,th=220/targetScale,overlap=Math.min(g.L,g.D)*.8,pad=Math.max(g.L,g.D)*2.5,totalW=g.W+2*pad,totalH=g.H+2*pad,nx=Math.max(1,Math.ceil((totalW-overlap)/(tw-overlap))),ny=Math.max(1,Math.ceil((totalH-overlap)/(th-overlap)));
    if(nx*ny>1&&nx*ny<=120)for(let r=0;r<ny;r++)for(let c=0;c<nx;c++){const tile={x:-pad+c*(tw-overlap),y:-pad+r*(th-overlap),w:tw,h:th};out+=`<section class="tile-page"><h2>Chart tile ${r+1}.${c+1} · ${ny} rows × ${nx} columns of pages</h2><p>Page rows run top to bottom; bead row numbers increase from bottom to top. Neighboring pages overlap slightly. Use the overview to position each tile.</p>${chartSVG({symbols:true,highlight:false,selected:false,exporting:true,tile})}</section>`;}
    out+=`<section class="print-legend"><h2>Color key & materials</h2><p>These are screen approximations to match to your beads. Counts include all background beads and count each RAW shared bead once.</p><table class="legend-table"><thead><tr><th>Code</th><th>Color</th><th>Beads</th><th>With 10% spare</th></tr></thead><tbody>${state.palette.map((h,i)=>`<tr><td>${mini(i)} ${E.code(i)}</td><td>${colorName(h)} · ${h}</td><td>${cc[i]}</td><td>${Math.ceil(cc[i]*1.1)}</td></tr>`).join('')}</tbody></table><h2>Before you stitch</h2><p>Work with the chart fixed: rows count upward from the bottom and columns count left to right. Use the guide's pickup order. Generic bead size: ${g.L} mm along the hole × ${g.D} mm diameter. Dimensions exclude finishing and vary with tension; make a swatch.</p><p>${g.stitch==='peyote'?'The starter interleaves rows 2 and 1. Follow the starter sequence exactly: P2-1, P1-1, P2-2, P1-2, and so on. Row 3 adds beads right to left. P3-2 means row 3, second bead from the left in that stitch row. Chart columns label starter positions.':g.stitch==='raw'?'H IDs label horizontal bead boundaries from the bottom; V IDs label vertical beads in each band of units. Column positions count from the left. Unit 1.1 is the bottom-left unit. Pick adds a new bead; pass moves through a bead already present. The same ID always refers to the same physical bead. Each line first moves into position, then completes the ring.':'String row 1 left to right, then alternate pickup direction for each row. For every new bead, loop through the bead below, then back through the new bead. Reinforce and turn at row ends.'}</p><p>Use size 11/0 seed beads and 0.20–0.25 mm fishing line. Check repeated passages fit your actual bead holes. Stop beads, needle, line, clasps and decorative finishing are extra. Secure and weave in thread ends. This app creates full flat panels; shaping, joins, and 3D patterns require additional instructions.</p><p>Digital checks verify structure and bead accounting. Check motif likeness, thread passes, and tension with a physical sample.</p></section>`;
    out+='<section><h2>Construction guide</h2><table><thead><tr><th>Step</th><th>Pickup order / thread path</th></tr></thead><tbody>';
    for(const st of state.guide){const desc=st.kind==='unit'?`${st.travel.length?'Move through: '+st.travel.join(' → ')+'<br>':''}${st.ops.map(op=>`${op.kind.toUpperCase()} ${op.id} (${E.code(state.colors[idx.get(op.id)])})`).join(' → ')}<br>N ${st.cell.n}; E ${st.cell.e}; S ${st.cell.s}; W ${st.cell.w}`:E.runs(st.ids,g,state.colors).map(r=>`${r.count}${E.code(r.color)}`).join(' · ');out+=`<tr><td>${esc(st.label)}<br>${st.direction}</td><td>${desc}${st.kind==='foundation'?'<br>'+esc(st.note):''}</td></tr>`;}
    out+='</tbody></table><p>Technique references: Fire Mountain Gems, “How to Create an Even and Odd Count Peyote Stitch” and “How to Make a Right-Angle Weave.” Links are available in the app stitch guide and text export.</p></section>';$('printArea').innerHTML=out;$('modal').close();setTimeout(()=>window.print(),150);}
  function exportModal(){if(!state.validation?.valid){toast('Resolve the structure check before exporting.');return;}modal('Ready for the making.',`<p class="modal-copy">Take your pattern from the screen to your bead mat. Charts include symbols and a color key. The full printing option adds readable chart tiles and the construction guide.</p><div class="export-grid"><button class="export-option" id="downloadPng"><span data-icon="image"></span><span><b>Pattern image</b><small>PNG · a color chart with bead symbols and materials</small></span></button><button class="export-option" id="downloadSvg"><span data-icon="expand"></span><span><b>Scalable chart</b><small>SVG · crisp at any zoom, with symbols and a color key</small></span></button><button class="export-option" id="printBtn"><span data-icon="printer"></span><span><b>Print / Save as PDF</b><small>Chart tiles, color key, and the full construction guide</small></span></button><button class="export-option" id="downloadGuide"><span data-icon="book"></span><span><b>Construction guide</b><small>TXT · pickup order and bead IDs for every row or unit</small></span></button><button class="export-option" id="downloadMaterials"><span data-icon="grid"></span><span><b>Materials list</b><small>CSV · counts by color, plus a 10% spare allowance</small></span></button><button class="export-option" id="downloadProject"><span data-icon="save"></span><span><b>Editable project</b><small>JSON · source image, settings, edits, and your place</small></span></button></div><div class="modal-footer">${num(state.geometry.nodes.length)} beads · ${counts().filter(x=>x).length} colors · ${esc(stitchNames[state.geometry.stitch])}<br>Colors are screen approximations; match them to your supplies. ${state.geometry.stitch==='raw'?'All shared beads are counted once.':''} <button class="text-button" id="downloadBeads">Download bead-by-bead CSV</button></div>`);$('downloadPng').onclick=exportPNG;$('downloadSvg').onclick=()=>download(exportSVG().svg,'image/svg+xml','-pattern.svg');$('printBtn').onclick=printPattern;$('downloadGuide').onclick=()=>download(textGuide(),'text/plain;charset=utf-8','-guide.txt');$('downloadMaterials').onclick=()=>download(materialsCSV(),'text/csv;charset=utf-8','-materials.csv');$('downloadProject').onclick=saveProject;$('downloadBeads').onclick=()=>download(csv(),'text/csv;charset=utf-8','-beads.csv');}
  function helpModal(){modal('A pattern you can follow.',`<p class="modal-copy">Beadform translates the colors of an image onto the bead positions for your chosen stitch. Keep the chart upright: row numbers increase from the bottom. Tune the size and color count until the subject reads clearly, then paint any small details.</p><section class="technique-guide"><h3>Peyote, one bead at a time.</h3><p>The foundation has an even bead count and forms two interleaved rows. Subsequent rows add half that number, fitting into the staggered gaps. The guide gives the foundation stringing order, then alternates pickup direction from row 3 onward.</p><a href="https://www.firemountaingems.com/learn/categories/essential-resources/how-tos/H11S-video-tutorial-with-instructions.html" target="_blank" rel="noopener noreferrer">Learn even-count peyote · Fire Mountain Gems ↗</a></section><section class="technique-guide"><h3>Right-angle weave, a ring at a time.</h3><p>Each unit is a ring of four beads. Adjacent units share an edge bead. The first unit adds four beads; an extension adds three; an interior unit in a later row adds two. The companion lists each new bead and each pass through an existing bead, including movement between units.</p><p>H labels a horizontal bead, V a vertical bead. The first number counts the boundary or band up from the bottom; the second counts its position from the left. Pick adds a bead; pass reuses one. Click a bead to see its ID.</p><a href="https://www.firemountaingems.com/learn/categories/essential-resources/how-tos/4B05-video-tutorial-with-instructions.html" target="_blank" rel="noopener noreferrer">Learn four-bead RAW · Fire Mountain Gems ↗</a></section><section class="technique-guide"><h3>Square stitch, a tidy grid.</h3><p>Beads sit directly above one another. After stringing the foundation, attach each new bead to the one directly below with a square-stitch loop. Reinforce at row ends, then reverse direction. Your guide lists only the new beads in pickup order.</p></section><section class="technique-guide"><h3>Give your motif enough room.</h3><ul><li>Use a clear silhouette or transparent cutout for the most readable animal or shape.</li><li>Increase the bead count if eyes, legs, or thin outlines disappear.</li><li>Start with a small palette. The optional speckle filter only softens low-contrast isolated colors.</li><li>Use Symbols for counting and Paint for fine corrections. Keyboard: Ctrl/Cmd + Z to undo; Escape to leave an expanded chart.</li></ul></section><section class="technique-guide"><h3>What's possible in this version?</h3><p>Full flat panels with a real bead in every background position. Checks cover the even peyote foundation, complete RAW units, connected beadwork, color assignments, and adding each physical bead exactly once. Make a sample to check tension, final size, and likeness. Color names and measurements are generic; no brand-specific color match is claimed.</p></section><section class="technique-guide"><h3>now, in three dimensions.</h3><p>Choose “3D creatures” to build a whole project from an image outline or a description. Text and full image interpretation use the connected generation service. The 3D studio includes an outline editor, a rotatable model, bead-and-thread diagrams, and movement replay. Its cubic structure produces stepped curves and needs physical sample testing.</p></section><div class="modal-footer">Flat conversion and 3D outline tracing run in your browser. Optional text and image interpretation sends your selected input to the configured generation service. Open and save project files to keep your work between sessions.</div>`);}
  function fullGuide(){const isRaw=state.geometry.stitch==='raw';modal('Your full construction guide.',`<p class="modal-copy">${isRaw?'Follow the move-through beads, then each pick/pass operation. Unit numbering follows chart coordinates from bottom left; work across alternate rows in opposite directions.':'Numbers tell you how many beads to pick up in each color. Follow the direction shown for each row, with the chart held upright.'} Select a step to highlight it in the studio.</p><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>Step</th><th>${isRaw?'Ring instructions':'New beads in pickup order'}</th></tr></thead><tbody>${state.guide.map((st,i)=>`<tr><td><button class="text-button" data-go="${i}">${esc(st.label)}</button><div class="direction">${st.direction}</div></td><td>${isRaw?rawHTML(st):runHTML(st.ids)}</td></tr>`).join('')}</tbody></table></div><div class="modal-footer"><button class="button secondary" id="guideTextExport">${icon('download')} Download full text guide</button></div>`);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.highlight=true;goStep(+b.dataset.go);$('modal').close();});$('guideTextExport').onclick=()=>download(textGuide(),'text/plain;charset=utf-8','-guide.txt');}
  function readSetting(id){const s=state.settings;let v=+$(id).value;if(!Number.isFinite(v)||$(id).value===''){syncInputs();return;}const input=$(id);v=E.clamp(v,+input.min,+input.max);if(['width','rows'].includes(id)){v=Math.round(v);if(id==='width'&&s.stitch==='peyote')v=Math.round(v/2)*2;}if(['beadLength','beadDiameter'].includes(id))v=Math.round(v*10)/10;settingsChange(id,v);}
  $('uploadZone').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>upload(e.target.files[0]);
  for(const ev of ['dragenter','dragover'])$('uploadZone').addEventListener(ev,e=>{e.preventDefault();$('uploadZone').classList.add('dragover');});
  for(const ev of ['dragleave','drop'])$('uploadZone').addEventListener(ev,e=>{e.preventDefault();$('uploadZone').classList.remove('dragover');if(ev==='drop')upload(e.dataTransfer.files[0]);});
  document.querySelectorAll('[data-stitch]').forEach(b=>b.onclick=()=>{const stitch=b.dataset.stitch;if(stitch===state.settings.stitch)return;confirmReset(()=>{const preset=stitch==='raw'?{width:16,rows:16,beadLength:1.3,beadDiameter:2}:stitch==='square'?{width:36,rows:30,beadLength:1.3,beadDiameter:2}:{width:40,rows:56,beadLength:1.3,beadDiameter:2};Object.assign(state.settings,preset,{stitch});syncInputs();generate(true);toast(stitch==='raw'?'RAW counts units across; each unit shares beads with its neighbors.':stitch==='peyote'?'An even foundation makes the first two peyote rows.':'Square stitch aligns beads in a complete grid.');});});
  for(const id of ['width','rows','beadLength','beadDiameter'])$(id).onchange=()=>readSetting(id);
  for(const id of ['maxColors','scale','contrast']){$(id).oninput=()=>{$(id+'Value').value=$(id).value+(id==='scale'?'%':'');};$(id).onchange=()=>settingsChange(id,+$(id).value);}
  $('fit').onchange=()=>settingsChange('fit',$('fit').value);$('background').onchange=()=>settingsChange('background',$('background').value);$('simplify').onchange=()=>settingsChange('simplify',$('simplify').checked);$('rotateBtn').onclick=()=>settingsChange('rotation',(state.settings.rotation+90)%360);
  for(const v of ['beads','symbols','source'])$(v+'View').onclick=()=>{state.view=v;renderChart();};
  $('zoomIn').onclick=()=>{state.zoom=Math.min(400,state.zoom+25);renderChart();};$('zoomOut').onclick=()=>{state.zoom=Math.max(50,state.zoom-25);renderChart();};$('zoomReset').onclick=()=>{state.zoom=100;renderChart();};$('expandBtn').onclick=()=>{$('board').classList.toggle('expanded');$('expandBtn').setAttribute('aria-label',$('board').classList.contains('expanded')?'Close expanded pattern':'Expand pattern');};
  $('inspectTool').onclick=()=>setTool('inspect');$('paintTool').onclick=()=>setTool('paint');
  function undo(){if(!state.undo.length)return;const u=state.undo.pop();Object.assign(state,u);renderAll();toast('Last edit undone.');}$('undoBtn').onclick=undo;
  $('patternStage').addEventListener('pointerdown',e=>{const bead=e.target.closest('[data-bead]');if(!bead)return;if(state.tool==='paint'&&e.button===0){e.preventDefault();$('patternStage').setPointerCapture?.(e.pointerId);painting=true;paintChanged=false;selectBead(bead.dataset.bead,true);}else selectBead(bead.dataset.bead);});
  $('patternStage').addEventListener('pointermove',e=>{if(!painting||state.tool!=='paint')return;const bead=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-bead]');if(bead)selectBead(bead.dataset.bead,true);});
  function finishPainting(){if(!painting)return;painting=false;if(paintChanged){renderPalette();renderStats();renderGuide();}paintChanged=false;}
  window.addEventListener('pointerup',finishPainting);window.addEventListener('pointercancel',finishPainting);window.addEventListener('blur',finishPainting);
  $('resetBtn').onclick=()=>confirmReset(()=>{generate();toast('Pattern regenerated from your original image.');});
  $('prevStep').onclick=()=>goStep(state.step-1);$('nextStep').onclick=()=>goStep(state.step+1);$('jumpStep').onchange=()=>goStep(Math.round(+$('jumpStep').value||1)-1);$('highlight').onchange=()=>{state.highlight=$('highlight').checked;if(state.highlight&&state.view==='source')state.view='beads';renderChart();};
  $('helpBtn').onclick=helpModal;$('scopeBtn').onclick=helpModal;$('allGuideBtn').onclick=fullGuide;$('exportBtn').onclick=exportModal;$('saveProjectBtn').onclick=saveProject;$('openBtn').onclick=()=>$('projectInput').click();$('projectInput').onchange=e=>importProject(e.target.files[0]);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')$('board').classList.remove('expanded');if(window.BeadformMode!=='volume'&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)) {e.preventDefault();undo();}});
  $('projectTitle').onchange=()=>{if(!$('projectTitle').value.trim())$('projectTitle').value='My pattern';renderChart();};
  window.addEventListener('beforeunload',e=>{if(state.edits){e.preventDefault();e.returnValue='';}});
  window.Beadform={ui:{modal,toast,esc,icon,fillIcons,loadImage},state,generate,chartSVG,textGuide,csv,materialsCSV,exportSVG,sourceCanvas,sampleBeads,importProject,saveProject,printPattern,goStep,renderAll};
  initSamples();syncInputs();chooseSample('butterfly',true);
})();
